2826	void vit_patch_project(
2827	 torch::Tensor input,
2828	 torch::Tensor weight,
2829	 torch::Tensor bias,
2830	 torch::Tensor output,
2831	 int batch, int channels, int height, int width,
2832	 int patch_size, int d_model
2833	) {
2834	 TORCH_CHECK(input.is_cuda(), "vit_patch_project: input must be CUDA");
2835	 TORCH_CHECK(height % patch_size == 0 && width % patch_size == 0,
2836	 "vit_patch_project: image dims must be divisible by patch_size");
2837	 int num_patches = (height / patch_size) * (width / patch_size);
2838	 int patch_dim = patch_size * patch_size * channels;
2839	 TORCH_CHECK(input.numel() == (int64_t)batch * num_patches * patch_dim,
2840	 "vit_patch_project: input must be [B*num_patches*patch_dim]");
2841	 TORCH_CHECK(output.numel() == (int64_t)batch * num_patches * d_model,
2842	 "vit_patch_project: output must be [B*num_patches*d_model]");
2843	 cudaStream_t stream = default_stream();
2844	 cudaError_t err = cudaSuccess;
2845	 auto t = input.scalar_type();
2846	 const void* bias_ptr = bias.defined() && bias.numel() > 0 ? bias.data_ptr() : nullptr;
2847	 int a = ::sg::detect_arch();
2848	 if (a != 90) {
2849	 throw std::runtime_error(
2850	 "vit_patch_project: unsupported arch " + std::to_string(a));
2851	 }
2852	 if (t == torch::kFloat32) {
2853	 err = sg::sm90::models::vit::patch_project<float, float>(
2854	 input.data_ptr<float>(),
2855	 weight.data_ptr<float>(),
2856	 static_cast<const float*>(bias_ptr),
2857	 output.data_ptr<float>(),
2858	 batch, num_patches, patch_dim, d_model, stream);
2859	 } else if (t == torch::kBFloat16) {
2860	 err = sg::sm90::models::vit::patch_project<__nv_bfloat16, __nv_bfloat16>(
2861	 reinterpret_cast<const __nv_bfloat16*>(input.data_ptr()),
2862	 reinterpret_cast<const __nv_bfloat16*>(weight.data_ptr()),
2863	 static_cast<const __nv_bfloat16*>(bias_ptr),
2864	 reinterpret_cast<__nv_bfloat16*>(output.data_ptr()),
2865	 batch, num_patches, patch_dim, d_model, stream);
2866	 } else if (t == torch::kFloat16) {
2867	 err = sg::sm90::models::vit::patch_project<__half, __half>(
2868	 reinterpret_cast<const __half*>(input.data_ptr()),
2869	 reinterpret_cast<const __half*>(weight.data_ptr()),
