3164	 torch::Tensor grad_A, torch::Tensor grad_B,
3165	 int batch, int seq_len, int d_state
3166	) {
3167	 (void)out; // not used: backward recomputes h from forward inputs
3168	 TORCH_CHECK(grad_out.is_cuda() && u.is_cuda() && delta.is_cuda()
3169	 && A.is_cuda() && B.is_cuda() && state.is_cuda(),
3170	 "mamba_selective_scan_backward: all tensors must be on CUDA");
3171	 auto stream = cur_stream();
3172	 const int sg_arch = ::sg::detect_arch();
3173	
3174	 auto run = [&](auto dummy) {
3175	 using scalar_t = decltype(dummy);
3176	 cudaError_t err;
3177	 if (sg_arch == 90) {
3178	 err = ::sg::sm90::models::mamba::selective_scan_bwd<scalar_t>(
3179	 ctptr<scalar_t>(grad_out),
3180	 ctptr<scalar_t>(u), ctptr<scalar_t>(delta),
3181	 ctptr<scalar_t>(A), ctptr<scalar_t>(B),
3182	 ctptr<scalar_t>(state),
3183	 tptr<scalar_t>(grad_u), tptr<scalar_t>(grad_delta),
3184	 tptr<scalar_t>(grad_A), tptr<scalar_t>(grad_B),
3185	 batch, seq_len, d_state, stream);
3186	 }
3187	#if defined(WITH_HIP)
3188	 else if (sg_arch == 942) {
3189	 err = ::sg::gfx942::models::mamba::selective_scan_bwd<scalar_t>(
3190	 ctptr<scalar_t>(grad_out),
3191	 ctptr<scalar_t>(u), ctptr<scalar_t>(delta),
3192	 ctptr<scalar_t>(A), ctptr<scalar_t>(B),
3193	 ctptr<scalar_t>(state),
3194	 tptr<scalar_t>(grad_u), tptr<scalar_t>(grad_delta),
3195	 tptr<scalar_t>(grad_A), tptr<scalar_t>(grad_B),
3196	 batch, seq_len, d_state, stream);
3197	 }
3198	#endif
3199	 else {
3200	 TORCH_CHECK(false,
3201	 "mamba_selective_scan_backward: unsupported arch ", sg_arch);
3202	 }
3203	 check_cuda(err, "selective_scan_backward");
3204	 };
3205	
3206	 switch (u.scalar_type()) {
3207	 case torch::kFloat32: run(float{}); break;
3208	 case torch::kFloat16: run(__half{}); break;
3209	 case torch::kBFloat16: run(__nv_bfloat16{}); break;
3210	 default:
3211	 TORCH_CHECK(false,
3212	 "mamba_selective_scan_backward: unsupported dtype ",
3213	 u.scalar_type());
3214	 }
3215	}
