2	// dispatch.cpp — single-source arch detection + fused_step dispatch
3	//
4	// Arch-honest LOUD-GATE dispatch (Phase 8). The kernel source has real bodies
5	// only for sm_90/sm_90a (one CUDA tree, sg::sm90) and gfx942 (one HIP tree,
6	// sg::gfx942). detect_arch_from_device() therefore returns 90 for NVIDIA
7	// major==9 and 942 for gfx942, and THROWS for any other CC/gfx (e.g. an A100
8	// sm_80, which has no TMA/WGMMA path) rather than silently running Hopper SASS
9	// on the wrong architecture. FORCE_ARCH is the explicit operator override.
10	// TPU arch is handled in Python via JAX.
11	// =====================================================================
12	
13	#include "helpers.h"
14	
15	#include <cstdlib>
16	#include <cstring>
17	#include <limits>
18	#include <stdexcept>
19	#include <string>
20	#include <unordered_map>
21	
22	#if defined(WITH_CUDA) && !defined(WITH_HIP)
23	 #include <cuda_runtime.h>
24	 #include <c10/cuda/CUDAStream.h>
25	#elif defined(WITH_HIP)
26	 #include <hip/hip_runtime.h>
27	 #include <c10/hip/HIPStream.h>
28	#endif
29	
30	// PHASE 1 — the TRUE L3 fused megakernel for (transformer_decoder × adamw): ONE
31	// persistent kernel runs the REAL decoder fwd+bwd + AdamW, no surrogate, no
32	// intermediate launches. Included at GLOBAL scope (it opens sg::fused::sm90 and
33	// pulls megakernel_common.cuh which opens sg::fused — both must NOT nest under
34	// dispatch.cpp's own `namespace sg {`). The token path is carried through the
35	// EXISTING fused_step pybind arity (the py::arg list in bindings.cpp pins it) by
36	// reinterpreting the `input` tensor as int32 tokens++targets; the workspace is
37	// device scratch allocated in fused_step (never crosses the ABI). fused_step's
38	// decoder branch (below) calls sg::fused::sm90::launch_fused_decoder_megakernel.
39	#if defined(WITH_CUDA) && !defined(WITH_HIP)
40	#include "csrc/fused/sm_90/fused_decoder_megakernel.cuh"
41	#endif
42	
43	namespace sg {
44	
45	namespace {
46	
47	int detect_arch_from_env() {
48	 const char* force = std::getenv("FORCE_ARCH");
49	 if (!force) return -1;
50	 std::string s(force);
51	 // TPU is handled in Python; not valid for C++ dispatch.
52	 if (s.rfind("tpu", 0) == 0) {
53	 throw std::runtime_error(
54	 "FORCE_ARCH=" + s + " is not a GPU arch; TPU dispatch is handled "
55	 "in Python via JAX.");
56	 }
57	 // AMD: any gfx target (and the bare 942 form) -> the gfx942 impl.
58	 if (s == "942" || s.rfind("gfx", 0) == 0) return 942;
59	 // NVIDIA: any sm_* / smXX form -> the sm90 impl.
60	 if (s.rfind("sm_", 0) == 0 || s.rfind("sm", 0) == 0) return 90;
61	 // Bare numeric compute capability (e.g. "70", "90", "120") -> NVIDIA.
62	 if (!s.empty() && s.find_first_not_of("0123456789") == std::string::npos)
63	 return 90;
64	 throw std::runtime_error(
65	 "FORCE_ARCH=" + s +
66	 " not recognized. Use an NVIDIA arch (sm_70..sm_120 or a numeric "
67	 "compute capability), an AMD arch (gfx906..gfx1201), or run TPU via "
68	 "Python/JAX.");
69	}
70	
71	int detect_arch_from_device() {
72	#if defined(WITH_CUDA) && !defined(WITH_HIP)
73	 int dev = 0;
74	 cudaError_t err = cudaGetDevice(&dev);
75	 if (err != cudaSuccess) {
76	 throw std::runtime_error(
77	 std::string("cudaGetDevice failed: ") + cudaGetErrorString(err));
78	 }
79	 // Query only the compute-capability attributes (cheap device-attribute
80	 // reads) instead of the full cudaGetDeviceProperties struct copy.
81	 int major = 0, minor = 0;
82	 err = cudaDeviceGetAttribute(&major, cudaDevAttrComputeCapabilityMajor, dev);
83	 if (err != cudaSuccess) {
84	 throw std::runtime_error(
85	 std::string("cudaDeviceGetAttribute(ComputeCapabilityMajor) failed: ") +
86	 cudaGetErrorString(err));
87	 }
88	 err = cudaDeviceGetAttribute(&minor, cudaDevAttrComputeCapabilityMinor, dev);
89	 if (err != cudaSuccess) {
90	 throw std::runtime_error(
91	 std::string("cudaDeviceGetAttribute(ComputeCapabilityMinor) failed: ") +
92	 cudaGetErrorString(err));
93	 }
94	 int sm = major * 10 + minor;
95	 // ARCH-HONEST DISPATCH (Stage 4): route per the REAL compute capability,
96	 // not "any NVIDIA -> 90". The shipped device code has ONE NVIDIA kernel
97	 // BODY: the sm_90a Hopper impl (TMA / wgmma — instructions that do not
98	 // exist on Ampere/Ada). setup.py emits SASS for every CC the toolchain
99	 // accepts plus a PTX fallback, but that PTX is lowered from sm_90a-gated
100	 // source, so it cannot JIT-forward to sm_80/sm_86/sm_89 — an A100 routed
101	 // to the sm_90a path would hit an illegal-instruction fault (or worse,
102	 // undefined behavior), not a clean error.
103	 //
104	 // POLICY: LOUD-GATE. We accept the Hopper family (sm_90 / sm_90a, i.e.
105	 // major == 9) and route it to impl 90. Every other NVIDIA CC fails loudly
106	 // here. This is the truthful option because only sm_90a has a real kernel
107	 // body — there is no sm_80/sm_86/sm_89 impl to route to. If a per-CC body
108	 // is ever added, give it its own selector value and a case here.
109	 if (major == 9) return 90;  // Hopper (sm_90 / sm_90a)
110	 throw std::runtime_error(
111	 "Detected sm_" + std::to_string(sm) +
112	 ": no kernel body for this NVIDIA compute capability. The shipped "
113	 "device code has only the sm_90a (Hopper) body, whose TMA/wgmma "
114	 "instructions are not valid on this arch and cannot be JIT-forwarded "
115	 "from the embedded PTX. Supported: sm_90a (NVIDIA), gfx942 (AMD). "
116	 "Set FORCE_ARCH=sm_90 only on a real Hopper device.");
117	#elif defined(WITH_HIP)
118	 int dev = 0;
119	 hipError_t err = hipGetDevice(&dev);
120	 if (err != hipSuccess) {
121	 throw std::runtime_error(
122	 std::string("hipGetDevice failed: ") + hipGetErrorString(err));
123	 }
124	 hipDeviceProp_t prop;
125	 err = hipGetDeviceProperties(&prop, dev);
126	 if (err != hipSuccess) {
127	 throw std::runtime_error(
128	 std::string("hipGetDeviceProperties failed: ") +
129	 hipGetErrorString(err));
130	 }
131	 std::string arch_name = prop.gcnArchName; // e.g. "gfx942:sramecc+:xnack-"
132	 auto colon = arch_name.find(':');
133	 if (colon != std::string::npos) arch_name = arch_name.substr(0, colon);
