155	int detect_arch() {
156	 // The GPU arch (and FORCE_ARCH) cannot change mid-process, so resolve it
157	 // exactly once. SG_DISPATCH invokes this up to n_params×ns_steps per step;
158	 // memoizing turns the per-dispatch getenv + device query into a single
159	 // C++11-guaranteed-thread-safe lazy init that subsequent calls read for free.
160	 static const int cached_arch = [] {
161	 int env_arch = detect_arch_from_env();
162	 if (env_arch >= 0) return env_arch;
163	 return detect_arch_from_device();
164	 }();
165	 return cached_arch;
166	}
