273	// Per-(device, n) reusable scratch for fused_step. The barrier counters and the
274	// `acts` proxy were previously reallocated (and `acts` memset over the full
275	// param size) on EVERY dispatch; sizes/offsets are constant for a given n.
276	// We persist them keyed by (device_index, n) and only reset the mutable parts
277	// (zero the 3 barrier counters + the acts buffer) per step. Behavior is
278	// identical — same zero-initialized scratch handed to the launcher — but the
279	// allocations/the full-size memset of sizes/offsets happen once per shape.
280	struct FusedScratch {
281	 torch::Tensor g_next;       // int32 [1]
282	 torch::Tensor g_arrived;    // int32 [1] (reinterpreted as unsigned)
283	 torch::Tensor g_generation; // int32 [1] (reinterpreted as unsigned)
284	 torch::Tensor sizes;        // int32 [1] = n  (constant per n)
285	 torch::Tensor offsets;      // int32 [1] = 0  (constant)
286	 torch::Tensor acts;         // float [numel(params)] proxy buffer
287	};
288	
289	// Keyed by (device_index, n). n disambiguates differing param shapes on the
290	// same device; acts is sized to params.numel() (== n here, single flat tensor).
291	inline FusedScratch& fused_scratch_for(const torch::Tensor& params, int64_t n) {
292	 static std::unordered_map<long long, FusedScratch> cache;
293	 const long long dev_idx =
294	 params.device().is_cuda() ? static_cast<long long>(params.device().index())
295	 : -1LL;
296	 const long long key = (dev_idx << 40) ^ static_cast<long long>(n);
297	 auto it = cache.find(key);
298	 if (it == cache.end()) {
299	 auto opts_i =
300	 torch::TensorOptions().device(params.device()).dtype(torch::kInt32);
301	 FusedScratch s;
302	 s.g_next = torch::zeros({1}, opts_i);
303	 s.g_arrived = torch::zeros({1}, opts_i);
304	 s.g_generation = torch::zeros({1}, opts_i);
305	 s.sizes = torch::full({1}, n, opts_i); // constant for this n
306	 s.offsets = torch::zeros({1}, opts_i); // constant
307	 s.acts = torch::zeros_like(params);
308	 it = cache.emplace(key, std::move(s)).first;
309	 } else {
310	 // Reset only the mutable scratch; sizes/offsets are invariant for this n.
311	 it->second.g_next.zero_();
312	 it->second.g_arrived.zero_();
313	 it->second.g_generation.zero_();
314	 it->second.acts.zero_();
315	 }
316	 return it->second;
317	}
318	#endif
