320	#if defined(WITH_CUDA) && !defined(WITH_HIP)
321	// PHASE-1 decoder L3-REAL scratch: the per-CTA grad-partial workspace + barrier
322	// counters + the int32 sizes/offsets task table (one task per parameter tensor,
323	// for the reduce + optimizer phases). The workspace is nCTA*total grad partials
324	// + nCTA loss partials; we size it for nCTA = #SMs (the launcher pins one CTA per
325	// SM). Persisted + reset per step like FusedScratch (the big workspace is zeroed
326	// IN-KERNEL by phase P0, so the host only resets the barrier/task counters here).
327	struct DecoderScratch {
328	 torch::Tensor g_next;        // int32 [1]
329	 torch::Tensor g_arrived;     // int32 [1] (unsigned-reinterpreted)
330	 torch::Tensor g_generation;  // int32 [1] (unsigned-reinterpreted)
331	 torch::Tensor sizes;         // int32 [kDecNumTensors] per-tensor numel
332	 torch::Tensor offsets;       // int32 [kDecNumTensors] per-tensor element offset
333	 torch::Tensor grad;          // float [total] reduced grad
334	 torch::Tensor workspace;     // float [nCTA*total + nCTA] partials + loss slots
335	 int n_ctas = 0;
336	};
337	
338	inline DecoderScratch& decoder_scratch_for(const torch::Tensor& params) {
339	 static std::unordered_map<long long, DecoderScratch> cache;
340	 const long long dev_idx =
341	 params.device().is_cuda() ? static_cast<long long>(params.device().index())
342	 : -1LL;
343	 const long long key = dev_idx;   // one decoder shape per device (fixed total)
344	 auto it = cache.find(key);
345	 const int64_t total = sg::fused::sm90::kDecTotalElems;
346	 if (it == cache.end()) {
347	 int dev = params.device().is_cuda() ? params.device().index() : 0;
348	 int n_sms = 1;
349	 cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
350	 auto opts_i =
351	 torch::TensorOptions().device(params.device()).dtype(torch::kInt32);
352	 auto opts_f =
353	 torch::TensorOptions().device(params.device()).dtype(torch::kFloat32);
354	 DecoderScratch s;
355	 s.g_next = torch::zeros({1}, opts_i);
356	 s.g_arrived = torch::zeros({1}, opts_i);
357	 s.g_generation = torch::zeros({1}, opts_i);
358	 // Per-tensor sizes/offsets from the generated layout (single source of truth).
359	 // Host mirror of kDecSizes/kDecOffsets (the device __constant__ arrays are not
360	 // host-addressable, so we build the int32 tensors from the same values).
361	 auto sizes_cpu = torch::empty({sg::fused::sm90::kDecNumTensors},
362	 torch::TensorOptions().dtype(torch::kInt32));
363	 auto off_cpu = torch::empty({sg::fused::sm90::kDecNumTensors},
364	 torch::TensorOptions().dtype(torch::kInt32));
365	 int* sp = sizes_cpu.data_ptr<int>();
366	 int* op = off_cpu.data_ptr<int>();
367	 int acc = 0;
368	 // Rebuild from the host-side layout tables in decoder_layout.cuh's check ns.
369	 for (int i = 0; i < sg::fused::sm90::kDecNumTensors; ++i) {
370	 sp[i] = sg::fused::sm90::dec_layout_check::kSizes[i];
371	 op[i] = sg::fused::sm90::dec_layout_check::kOffsets[i];
372	 TORCH_CHECK(op[i] == acc, "decoder_layout host/device offset mismatch");
373	 acc += sp[i];
374	 }
375	 TORCH_CHECK((int64_t)acc == total, "decoder_layout host total mismatch");
376	 s.sizes = sizes_cpu.to(params.device());
377	 s.offsets = off_cpu.to(params.device());
378	 s.grad = torch::zeros({total}, opts_f);
379	 // workspace: nCTA*total partials + nCTA loss slots. Zeroed in-kernel (P0);
380	 // allocate (not zero) — the in-kernel P0 + the loss reduce overwrite it.
381	 s.workspace = torch::empty({(int64_t)n_sms * total + n_sms}, opts_f);
382	 s.n_ctas = n_sms;
383	 it = cache.emplace(key, std::move(s)).first;
384	 } else {
385	 it->second.g_next.zero_();
386	 it->second.g_arrived.zero_();
387	 it->second.g_generation.zero_();
388	 }
389	 return it->second;
390	}
391	#endif
