395	// NOTE: the default argument VALUES live on the declaration in helpers.h (which
396	// bindings.cpp sees for the py::arg defaults). C++ forbids repeating a default
397	// argument on both the declaration and the definition, so the definition below
398	// lists the parameters WITHOUT defaults. Keep the two signatures in lock-step:
399	// (model, optimizer, params, input, grad, state, lr, beta1, beta2, eps,
400	//  weight_decay, alpha, lamb, gamma, gate, d_factor, bc1, bc2, neg_lr_scale,
401	//  decay_factor, beta, alpha_max, step, opt_only).
402	void fused_step(const std::string& model, const std::string& optimizer,
403	 torch::Tensor params, torch::Tensor input,
404	 torch::Tensor grad, torch::Tensor state, float lr,
405	 // FULL scalar set (C2-gap fix). apply_optimizer<> reads every one of
406	 // these; before this widening only `lr` was bound and the rest sat at
407	 // FusedOptState defaults (bc1/bc2/gate/d_factor == 1.0 → NO bias
408	 // correction, SG gating + Prodigy d-adaptation inert). bc1/bc2 are
409	 // un-inverted (= 1 - beta^step); the caller computes them from the shared
410	 // step counter (valid because all race params step together — the
411	 // megakernel treats the flat param as one task with one bc pair).
412	 float beta1, float beta2, float eps,
413	 float weight_decay, float alpha, float lamb,
414	 float gamma, float gate, float d_factor,
415	 float bc1, float bc2,
416	 float neg_lr_scale, float decay_factor,
417	 float beta, float alpha_max,
418	 int64_t step,
419	 // Tier selector. opt_only=true → L1: fused optimizer TAIL only; the kernel
420	 // reads the REAL grad from `grad` (framework-computed) and applies the
421	 // canonical update — the numerically-faithful path the race uses.
422	 // opt_only=false → L3: the kernel also runs the SURROGATE element-local
423	 // model fwd/bwd (model_stages.*), whose loss does NOT match the real
424	 // Transformer/ViT/Mamba graph (see BUILD_AND_VALIDATE.md).
425	 bool opt_only) {
426	 int arch = detect_arch();
427	 std::string arch_str = (arch == 90) ? "sm_90"
428	 : (arch == 942) ? "gfx942" : "tpu_v6e";
429	 // `gamma` is carried for ABI completeness / forward-compat (the directive's
430	 // scalar set lists it). No current apply_optimizer<> branch consumes a gamma
431	 // term — SG15's gamma_alpha folds into the host-side alpha schedule (it
432	 // arrives here already baked into `alpha`), so binding it again would double-
433	 // apply. Kept in the ABI so a future cell can read it without re-widening.
434	 (void)gamma;
435	
436	 const std::string cell = wired_fused_cell(model, optimizer, arch);
437	 if (cell.empty()) {
438	 // §1.12 fall-through: no fused TU for this cell. The caller uses the
439	 // existing per-op dispatch (the per-optimizer *_fused_step bindings),
440	 // which is untouched. We surface a clear, non-silent signal.
441	 throw std::runtime_error(
442	 "no fused TU for (" + model + ", " + optimizer + ", " + arch_str +
443	 "); use the per-op path. Wired L3 cells: (mamba3,adamw), "
444	 "(transformer_decoder,lion), (vit,supergrok15).");
445	 }
446	
447	#if defined(WITH_CUDA) && !defined(WITH_HIP)
448	 // ── PHASE 1: the TRUE L3 fused decoder megakernel (real fwd+bwd+adamw). ──
449	 // Fires for (transformer_decoder, adamw, !opt_only): ONE persistent kernel,
450	 // no surrogate, no intermediate launches. The token path is carried through
451	 // the EXISTING fused_step arity (the pybind py::arg list pins it) by reading
452	 // tokens/targets from the int32-reinterpreted `input` tensor:
453	 //   input = int32 [B*(kSeq+1)]  (first B*kSeq tokens row-major, last B targets)
454	 // and `state` = float [3*total + 1] ([m|v|extra] + a trailing loss slot the
455	 // kernel writes the mean loss into, which the Python wrapper reads back). The
456	 // workspace (nCTA*total grad partials + nCTA loss partials) is device scratch
457	 // allocated here — it never crosses the ABI. S/vocab/d are compile-time
458	 // (kSeq/kVocab/kD); B is derived from input.numel(). This leaves the 33
459	 // generated surrogate cells untouched (their surrogate-L3 path is now
460	 // unreachable dead code; see BUILD_AND_VALIDATE.md PHASE-1).
461	 if (arch == 90 && model == "transformer_decoder" && optimizer == "adamw"
462	 && !opt_only) {
463	 namespace dms = sg::fused::sm90;
464	 const int64_t total = dms::kDecTotalElems;
465	 TORCH_CHECK(params.numel() == total,
466	 "fused decoder megakernel: params has ", params.numel(),
467	 " elements but the small decoder has ", total,
468	 ". Pass the flat concat of named_parameters() in order.");
469	 TORCH_CHECK(params.scalar_type() == torch::kFloat32 && params.is_contiguous(),
470	 "fused decoder megakernel: params must be contiguous fp32.");
471	 // input = int32 tokens(B*kSeq) ++ targets(B). B = numel/(kSeq+1).
472	 TORCH_CHECK(input.scalar_type() == torch::kInt32 && input.is_contiguous(),
473	 "fused decoder megakernel: input must be contiguous int32 "
474	 "(packed tokens[B*kSeq]++targets[B]).");
475	 const int64_t in_n = input.numel();
476	 TORCH_CHECK(in_n % (dms::SG_DEC_SEQ + 1) == 0 && in_n > 0,
477	 "fused decoder megakernel: input.numel() (", in_n,
478	 ") must be B*(kSeq+1) = B*", dms::SG_DEC_SEQ + 1, ".");
479	 const int B = (int)(in_n / (dms::SG_DEC_SEQ + 1));
480	 // state = [m|v|extra] (3*total) + 1 loss slot.
481	 TORCH_CHECK(state.numel() >= 3 * total + 1 &&
482	 state.scalar_type() == torch::kFloat32 && state.is_contiguous(),
483	 "fused decoder megakernel: state must be contiguous fp32 with "
484	 ">= 3*total+1 = ", 3 * total + 1, " elements ([m|v|extra]+loss).");
485	
486	 DecoderScratch& dsc = decoder_scratch_for(params);
487	 // The launcher takes sg::fused::PersistentContext (the real substrate type
488	 // from megakernel_common.cuh, included transitively via the decoder mega
489	 // header). Build it directly from the scratch counters.
490	 sg::fused::PersistentContext ctx{
491	 dsc.g_next.data_ptr<int>(),
492	 reinterpret_cast<unsigned*>(dsc.g_arrived.data_ptr<int>()),
493	 reinterpret_cast<unsigned*>(dsc.g_generation.data_ptr<int>()),
494	 dms::kDecNumTensors,   // n_tasks = #parameter tensors (reduce + opt phases)
495	 0u};                   // n_ctas overwritten by the launcher (one CTA/SM)
496	
497	 float* m = state.data_ptr<float>();
498	 float* loss_slot = m + 3 * total;          // the trailing loss slot
499	 dms::DecoderTokenCtx tok_ctx{
500	 input.data_ptr<int>(),                 // tokens
501	 input.data_ptr<int>() + (int64_t)B * dms::SG_DEC_SEQ,  // targets
502	 B,
503	 dsc.workspace.data_ptr<float>(),
504	 loss_slot};
505	
506	 // Bind the AdamW state + the FULL scalar set (un-frozen bc1/bc2/...).
507	 dms::FusedOptState st;
508	 st.exp_avg = m;
509	 st.exp_avg_sq = m + total;
510	 dms::FusedScalars sc_scalars{
511	 lr, beta1, beta2, eps, weight_decay, bc1, bc2, alpha, beta, lamb,
512	 alpha_max, gate, d_factor, neg_lr_scale, decay_factor};
513	 dms::apply_scalars(st, sc_scalars);
514	 st.lr = lr;
515	
516	 cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
517	 cudaError_t err = dms::launch_fused_decoder_megakernel<dms::OptId::AdamW>(
518	 ctx, params.data_ptr<float>(), tok_ctx, dsc.grad.data_ptr<float>(),
519	 dsc.sizes.data_ptr<int>(), dsc.offsets.data_ptr<int>(),
520	 lr, static_cast<int>(step), st, stream);
521	 if (err != cudaSuccess)
522	 throw std::runtime_error(
523	 std::string("fused decoder megakernel launch failed: ") +
524	 cudaGetErrorString(err));
525	 return;
526	 }
527	
528	 if (arch == 90) {
529	 // Prepare the megakernel inputs from the tensors. The persistent scratch
530	 // (task counter + barrier state) is device-allocated and zero-initialized
531	 // here; the host launcher pins one CTA per SM. `state` carries the
532	 // optimizer state slices (m, v) concatenated; sizes/offsets describe the
533	 // per-parameter-tensor layout (here the single flattened tensor).
534	 //
535	 // Keep the element count in int64 at this boundary: a large flat param
536	 // ( > 2^31-1 elements ) truncated to `int` would wrap negative, making
537	 // the `3*n` state-size check pass spuriously and the `m + n` / `m + 2*n`
538	 // pointer offsets index out of bounds (silent OOB corruption). The
539	 // numel-derived state check and pointer math below all use this int64 n.
540	 const int64_t n = params.numel();
541	
542	 // Reusable per-(device,n) scratch: counters/acts reset, sizes/offsets fixed.
